"""KinyaShield guide: original answers to common digital-safety questions, in four languages.

Everything here was written for this project in its own words. Nothing is copied from books,
articles or other publications, so there is no third-party copyright in it. For official
details (laws, contacts, procedures) the answers send people to official sources instead of
quoting them.

Keywords: lower-case, accent-free. "word*" matches any word starting with "word".
Phrases (several words) are matched as a whole. fr, rw and sw text is DRAFT until reviewed.
"""

L = ["en", "fr", "rw", "sw"]

def _e(id_, related, title, kw, answer, steps):
    return {"id": id_, "related": related,
            "title": dict(zip(L, title)),
            "keywords": {l: [k for k in kw[i].split("|") if k] for i, l in enumerate(L)},
            "answer": dict(zip(L, answer)),
            "steps": {l: steps[i] for i, l in enumerate(L)}}

